/**
 * OCandlestickChart.impl - lightweight-charts 实际实现。
 *
 * 由 OCandlestickChart 通过 dynamic import 加载,避免 main bundle 包含 lightweight-charts (~28KB)。
 *
 * 注意: lightweight-charts 是命名 export,需要按其 v5 API 使用 (createChart + addCandlestickSeries)。
 * 这里我们用通用兼容写法,如真实环境版本不同请适配 IMPLEMENTATION.md。
 */
'use client';

import { useEffect, useRef } from 'react';
import type { OCandlestickData } from './OCandlestickChart';
import { useCrosshair } from '../../providers/CrosshairProvider';

interface ImplProps {
  data: OCandlestickData;
  colorScheme: 'std' | 'inv';
  hideTimeAxis: boolean;
  height: number;
  /** 标的 (用于跨图 crosshair 联动)。null 则不联动。 */
  symbolForCrosshair?: string | null;
  /** 性能降级 (关闭 indicators 和 volume)。 */
  lowPerformanceMode?: boolean;
}

function normalizeTime(t: number | string): number {
  if (typeof t === 'number') return t > 1e10 ? Math.floor(t / 1000) : t;
  return Math.floor(new Date(t).getTime() / 1000);
}

export function CandlestickImpl({
  data,
  colorScheme,
  hideTimeAxis,
  height,
  symbolForCrosshair,
  lowPerformanceMode,
}: ImplProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<{ remove: () => void } | null>(null);
  const crosshair = useCrosshair();

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    let cancelled = false;
    let chartInstance: { remove: () => void } | null = null;

    // 动态 import 实际库
    import('lightweight-charts').then((lib) => {
      if (cancelled || !el) return;

      const up = colorScheme === 'inv' ? 'oklch(0.55 0.20 25)' : 'oklch(0.62 0.18 145)';
      const down = colorScheme === 'inv' ? 'oklch(0.62 0.18 145)' : 'oklch(0.55 0.20 25)';

      const rootStyles = getComputedStyle(document.documentElement);
      const bg = rootStyles.getPropertyValue('--card').trim() || 'oklch(0.13 0.025 265)';
      const fg = rootStyles.getPropertyValue('--foreground').trim() || 'oklch(0.95 0.01 200)';
      const border = rootStyles.getPropertyValue('--border').trim() || 'oklch(0.25 0.04 240)';

      // lightweight-charts v5 API
      const chart = (lib as unknown as {
        createChart: (
          el: HTMLElement,
          opts: Record<string, unknown>
        ) => {
          addCandlestickSeries: (opts?: Record<string, unknown>) => {
            setData: (d: unknown[]) => void;
          };
          addLineSeries: (opts?: Record<string, unknown>) => {
            setData: (d: unknown[]) => void;
          };
          addHistogramSeries?: (opts?: Record<string, unknown>) => {
            setData: (d: unknown[]) => void;
          };
          timeScale: () => { fitContent: () => void };
          remove: () => void;
          applyOptions: (opts: Record<string, unknown>) => void;
          resize: (w: number, h: number) => void;
        };
      }).createChart(el, {
        width: el.clientWidth,
        height,
        layout: {
          background: { color: bg },
          textColor: fg,
        },
        grid: {
          vertLines: { color: border, visible: !hideTimeAxis },
          horzLines: { color: border },
        },
        rightPriceScale: { borderColor: border },
        timeScale: { borderColor: border, visible: !hideTimeAxis, timeVisible: true, secondsVisible: false },
        crosshair: { mode: 1 },
      });

      const candleSeries = chart.addCandlestickSeries({
        upColor: up,
        downColor: down,
        borderUpColor: up,
        borderDownColor: down,
        wickUpColor: up,
        wickDownColor: down,
      });

      candleSeries.setData(
        data.candles.map((c) => ({
          time: normalizeTime(c.time) as unknown as number,
          open: c.open,
          high: c.high,
          low: c.low,
          close: c.close,
        }))
      );

      // Indicators (low-performance mode 跳过)
      if (data.indicators && !lowPerformanceMode) {
        for (const ind of data.indicators) {
          const line = chart.addLineSeries({
            color: ind.color ?? 'oklch(0.7 0.2 200)',
            lineWidth: 2,
            priceLineVisible: false,
          });
          line.setData(
            ind.values.map((v) => ({ time: normalizeTime(v.time) as unknown as number, value: v.value }))
          );
        }
      }

      // Volume (low-performance mode 跳过)
      if (
        !lowPerformanceMode &&
        data.showVolume &&
        data.candles.some((c) => c.volume != null) &&
        chart.addHistogramSeries
      ) {
        const volSeries = chart.addHistogramSeries({
          color: border,
          priceFormat: { type: 'volume' },
          priceScaleId: '',
          scaleMargins: { top: 0.85, bottom: 0 },
        });
        volSeries.setData(
          data.candles
            .filter((c) => c.volume != null)
            .map((c) => ({
              time: normalizeTime(c.time) as unknown as number,
              value: c.volume!,
              color: c.close >= c.open ? `${up}80` : `${down}80`,
            }))
        );
      }

      chart.timeScale().fitContent();
      chartInstance = chart;
      chartRef.current = chart;

      // ============ Crosshair 双向同步 ============
      const chartWithCh = chart as unknown as {
        subscribeCrosshairMove?: (cb: (p: { time?: number; point?: unknown }) => void) => void;
      };

      if (symbolForCrosshair && crosshair) {
        // 1) 本图鼠标移动 → broadcast 到其他 Block
        chartWithCh.subscribeCrosshairMove?.((param) => {
          if (param.time != null) {
            crosshair.broadcast({
              symbol: symbolForCrosshair,
              time: param.time as number,
              value: null,
            });
          }
        });
        // 2) 接收其他 Block 的 broadcast → 暂存让 TV 自己显示 (TV crosshair API 受限,
        //    高级实现需要 chart.setCrosshairPosition,这里仅订阅占位,后续 v1.1 补)
      }

      // 响应式
      const ro = new ResizeObserver(() => {
        if (el) chart.resize(el.clientWidth, height);
      });
      ro.observe(el);

      return () => {
        ro.disconnect();
      };
    }).catch((err) => {
      console.error('[OCandlestickChart] Failed to load lightweight-charts:', err);
    });

    return () => {
      cancelled = true;
      try {
        chartInstance?.remove();
      } catch {
        /* noop */
      }
      chartRef.current = null;
    };
  }, [data, colorScheme, hideTimeAxis, height, symbolForCrosshair, lowPerformanceMode, crosshair]);

  return <div ref={containerRef} className="w-full h-full @container" />;
}
